"""The PTX comparison's cards (kernels/ptx.py), counted from real nvcc output for sm_90a (compiled on a laptop with no
GPU) and from a hand-written snippet with Hopper features."""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from kernels.ptx import card, entries, features, render  # noqa: E402

