HOPPER = """
.visible .entry gemm(
	.param .u64 a
)
{
	.reg .b32 	%r<40>;
	.reg .f32 	%f<64>;
	.shared .align 128 .b8 smem[49152];
	setmaxnreg.inc.sync.aligned.u32 240;
	mbarrier.init.shared.b64 [smem], 1;
	cp.async.bulk.tensor.2d.shared::cluster.global.mbarrier::complete_tx::bytes [smem], [a, {%r1, %r2}], [smem];
	wgmma.mma_async.sync.aligned.m64n128k16.f32.bf16.bf16 {%f1}, %r3, %r4, 1, 1, 1, 0, 0;
	wgmma.mma_async.sync.aligned.m64n128k16.f32.bf16.bf16 {%f2}, %r3, %r4, 1, 1, 1, 0, 0;
	@%p1 bra $L1;
	ld.global.v4.u32 {%r5, %r6, %r7, %r8}, [a];
$L1:
	ret;
}
"""


def test_a_real_kernels_card_from_nvcc_output():
    ptx = RMSNORM
    (name,) = entries(ptx)
    f = features(entries(ptx)[name])
    assert "rmsnorm" in name and f["barrier"] == 2 and f["ld_shared"] == 3 and f["uses"] == []
    assert f["widest_vector"] == 1 and f["static_shared_bytes"] == 0      # extern shared: sized at launch


def test_hopper_features_are_counted_and_the_fastest_is_shown_first():
    f = features(entries(HOPPER)["gemm"])
    assert f["wgmma"] == 2 and f["tma"] == 1 and f["setmaxnreg"] == 1 and f["static_shared_bytes"] == 49152
    assert f["uses"] == ["mbarrier", "setmaxnreg", "tma", "wgmma"] and f["widest_vector"] == 4
    assert f["declared_registers"] == 104
    text = render([card("ours", RMSNORM, 0.031), card("theirs", HOPPER, 0.02)])
    assert text.index("theirs") < text.index("ours") and "0.02 ms on our shapes" in text


SASS = """
        Function : _Z4gemmv
        /*0000*/                   MOV R1, c[0x0][0x28] ;
        /*0010*/                   USETMAXREG.DEALLOC.CTAPOOL 0x28 ;
        /*0020*/                   UTMALDG.2D [UR8], [UR4] ;
        /*0030*/                   HGMMA.64x128x16.F32.BF16 R24, gdesc[UR8], RZ ;
        /*0040*/               @P0 BRA 0x80 ;
        /*0050*/                   LDG.E.128 R4, desc[UR6][R2.64] ;
"""


def test_a_card_reads_sass_when_a_library_ships_no_ptx():
    c = card("lib", SASS)
    (f,) = c["per_kernel"].values()
    assert f["from"] == "sass" and f["wgmma"] == 1 and f["tma"] == 1 and f["setmaxnreg"] == 1 and f["branch"] == 1
    assert f["uses"] == ["setmaxnreg", "tma", "wgmma"]


